import pandas as pd

df = pd.read_excel('cms_nhe_source_of_funds.xlsx', sheet_name='Table 3', header=None)
col_2024 = [i for i, y in enumerate(df.iloc[1]) if str(y).strip() == '2024'][0]

candidates = ['Private Health Insurance', 'Medicare', 'Medicaid', 'Other Health Insurance Programs1']
cleaned_names = {'Private Health Insurance': 'Private Health Insurance', 'Medicare': 'Medicare', 'Medicaid': 'Medicaid', 'Other Health Insurance Programs1': 'Other Health Insurance Programs'}

spending = {}
for i in range(3, 16):
    item = str(df.iloc[i, 0]).strip()
    if item in candidates:
        clean_name = item.rstrip('12')
        spending[clean_name] = float(df.iloc[i, col_2024])

sorted_items = sorted(spending.items(), key=lambda x: x[1], reverse=True)
result = [item[0] for item in sorted_items[:3]]
